// RegisterHandlers adds each server route to the EchoRouter.
func RegisterHandlers(router EchoRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, RegisterHandlersOptions{})
}

// RegisterHandlersWithBaseURL registers handlers and prepends BaseURL to the
// paths so the API can be served under a prefix.
func RegisterHandlersWithBaseURL(router EchoRouter, si ServerInterface, baseURL string) {
	RegisterHandlersWithOptions(router, si, RegisterHandlersOptions{BaseURL: baseURL})
}

// RegisterHandlersWithOptions registers handlers using the supplied options,
// including any per-operation middleware.
func RegisterHandlersWithOptions(router EchoRouter, si ServerInterface, options RegisterHandlersOptions) {

	wrapper := ServerInterfaceWrapper{
		Handler: si,
	}

	router.GET(options.BaseURL+"/projects/:project_id/boards", wrapper.ListBoards, options.OperationMiddlewares["listBoards"]...)
	router.POST(options.BaseURL+"/projects/:project_id/boards", wrapper.CreateBoard, options.OperationMiddlewares["createBoard"]...)
	router.DELETE(options.BaseURL+"/projects/:project_id/boards/:board_id", wrapper.DeleteBoard, options.OperationMiddlewares["deleteBoard"]...)
	router.GET(options.BaseURL+"/projects/:project_id/boards/:board_id", wrapper.GetBoard, options.OperationMiddlewares["getBoard"]...)
	router.PUT(options.BaseURL+"/projects/:project_id/boards/:board_id", wrapper.UpdateBoard, options.OperationMiddlewares["updateBoard"]...)
	router.POST(options.BaseURL+"/projects/:project_id/boards/:board_id/columns", wrapper.CreateBoardColumn, options.OperationMiddlewares["createBoardColumn"]...)
	router.DELETE(options.BaseURL+"/projects/:project_id/boards/:board_id/columns/:column_id", wrapper.DeleteBoardColumn, options.OperationMiddlewares["deleteBoardColumn"]...)
	router.PUT(options.BaseURL+"/projects/:project_id/boards/:board_id/columns/:column_id", wrapper.UpdateBoardColumn, options.OperationMiddlewares["updateBoardColumn"]...)
	router.GET(options.BaseURL+"/projects/:project_id/boards/:board_id/columns/:column_id/tasks", wrapper.ListBoardColumnTasks, options.OperationMiddlewares["listBoardColumnTasks"]...)
	router.POST(options.BaseURL+"/projects/:project_id/boards/:board_id/tasks/:task_id/move", wrapper.MoveBoardTask, options.OperationMiddlewares["moveBoardTask"]...)

}

